INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p996039-stat301', 'stk-user6966', 'STAT 301', 'info', '{"desc": "جودة المقرر بشكل عام\n\nالكتاب المستخدم من طبعة عام 1996 , ومعاه في نهاية الكتاب Flobby disk اذا تعرفوه. إنتبهوا تنزعوا الـattachment عن الـFlobby disk لأنكم بكذا ماراح تقدرون ترجعونه للشركة هههههههههههههه\n\nطبعاً للمعلومية , ترى الكتاب الحين واصل طبعة 2010 وحنا بالجامعة عندنا طبعة 1996\n\nالمواضيع التي يغطيها المقرر\n\nيغطي مواضيع مختلفة تتعلق بالإحتماليات منها\npermutations\ncombinations\nsample space and events\nconditional probability\nbayes formula\nindependent events\n\nrandom variables\ndistribution functions\nexpected value and variance\n\ncontinues random variables\njointly distribution raondom variables\nproperities of expectations\nlimit theoerms\n\nالكتاب المستخدم للمقرر\n\nما فهمت هالنقطة\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nالأمثلة لا تفي بالغرض لكنها جميلة إلى حد ما\nالأسئلة جداً جداً جداً جداً جداً جداً صعبة ! لدرجة أني دائماً كنت أقول “الكاتب لما كتب اسئلة الكتاب, ما عرف يحلهم” … ولو الأستاذ كتب أسئلة المياجر من أسئلة الكتاب نصاً , محد بيقدر يجيب A+\n\nطبعاً أسئلة الكتاب مقسمة إلى أقسام\nProblems + theoretical exercises + self test\n\nوجميعهاً صعبة جداً\n\nمدى فائدته في الناحية التطبيقية\n\nالإحتماليات من أقوى تطبيقات الإحصاء في الحياة, والكتاب يعلمك كيف تستعمل التباديل والتوافيق في حساب عدد الخيارات الممكنة , وكذلك الكتاب راح يعلمك كيفية المقامرة (gambling) عشان لما ترووح لـ لاس فيغاس تعرف كيف تخمّن.\n\nالكورس نفسه صعب , والدكتور وليد الصباح قال أنه صعب كما أنه مصمم للـ Advance undergraduate and graduate students\n\nالمادة ماهي رياضيات , ما يهم قد ايش تحل مسائل !!\nالمادة أقرب مثال لها هي ics . كل المطلوب منك تفهم صح !! لأن المسائل تجي مركبة ( يقدر يألف مسألة من راسه يعني ويقولك احسب احتمالية كذا ) .\n\nاهم شي يكون مخك شغّال صح\n\nالمهارات المطلوبة قبل الكورس :\nintegration with more than one variable\nlimits ( you must understand calculus clearly and perfectly\n\nواعذروني ان اسلوبي فيه جزء كبير من التحطيم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stat-301-intro-to-probability-theory/120636/2", "user": "user6966", "ts": 1330458366000, "tid": 120636, "pn": 2}}', 1330458366000, 1794774616, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
